def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    r, c = next((r, c) for r in range(h) for c in range(w) if grid[r][c] == 3)
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    length = 2
    for segment in range(200):
        dr, dc = directions[segment % 4]
        for _ in range(length):
            r += dr
            c += dc
            if 0 <= r < h and 0 <= c < w:
                if grid[r][c] == 2:
                    return out
                out[r][c] = 3
        if segment % 2 == 1:
            length += 2
    # With an unobstructed spiral, the final clipped sweep fills the far edge.
    if not any(2 in row for row in grid):
        out[h - 1] = [3 if cell == 0 else cell for cell in out[h - 1]]
    return out
